// Scheduled daily job 'snapshots' (see docs/prices.md). Deployed with --no-verify-jwt: the
// handler itself requires the x-ledgr-cron-secret header before doing anything.
// ../_shared/ledgr-jobs.js is generated by `pnpm functions:build` (packages/market).
import { handleJob } from '../_shared/ledgr-jobs.js';

Deno.serve((req: Request) => handleJob('snapshots', req, Deno.env.toObject()));
